  PasswordValidated: boolean;
  WithdrawedNumber: number;
  InputCard: BankCard;
  CardIDValidated: boolean;
  IsDeposit: boolean;
  IsWithdraw: boolean;
  DepositedNumber: number;
  /*SystemVariable End*/

  /*the card id and password is validated and the input card exist, then if the money is withdraw,
   *if print the withdrawed number or if it is deposit print the deposited number or print 0*/
  printReceipt(): number {
    /*Definition Start*/
    let inputBankCard: BankCard = l({
      logic: () =>
        getRepository(BankCard).find(
          (c: any) =>
            l({
              logic: () => c.CardID === this.InputCard,
              description: "c.CardID=InputCard",
            }).build().pass,
        ),
      description: "BankCard.allInstance()->any(c|c.CardID=InputCard)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => this.CardIDValidated,
        description: "CardIDValidated",
      })
        .and({
          logic: () => this.PasswordValidated,
          description: "PasswordValidated",
        })
        .and({
          logic: () => getRepository(BankCard).includes(this.InputCard),
          description: "BankCard.allInstance()->includes(InputCard)",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newResult: number;
    return l()
      .if({
        logic: () =>
          l({
            logic: () => this.IsDeposit,
            description: "IsDeposit",
          }),
        description: "IsDeposit",
        then: l({
          execute: () => this.DepositedNumber,
          description: "result=DepositedNumber",
