            description: "result=DepositedNumber",
          }),
          else: l({
            execute: () => 0,
            description: "result=0",
          }),
        }),
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { AutomatedTellerMachineSystem_AutoGenerated };

